{"protocolSection":{"identificationModule":{"nctId":"NCT02411994","orgStudyIdInfo":{"id":"KIT601714"},"organization":{"fullName":"Royal Tropical Institute","class":"OTHER"},"briefTitle":"Pyronaridine-artesunate and Artemether-lumefantrine for the Treatment of Paediatric Malaria","officialTitle":"Pyronaridine-artesunate and Artemether-lumefantrine for the Treatment of Paediatric Uncomplicated Falciparum Malaria in Western Kenya","acronym":"PAAL"},"statusModule":{"statusVerifiedDate":"2017-11","overallStatus":"COMPLETED","expandedAccessInfo":{"hasExpandedAccess":false},"startDateStruct":{"date":"2015-10"},"primaryCompletionDateStruct":{"date":"2017-08","type":"ACTUAL"},"completionDateStruct":{"date":"2017-08","type":"ACTUAL"},"studyFirstSubmitDate":"2015-04-03","studyFirstSubmitQcDate":"2015-04-07","studyFirstPostDateStruct":{"date":"2015-04-08","type":"ESTIMATED"},"lastUpdateSubmitDate":"2017-11-24","lastUpdatePostDateStruct":{"date":"2017-11-27","type":"ACTUAL"}},"sponsorCollaboratorsModule":{"responsibleParty":{"type":"SPONSOR"},"leadSponsor":{"name":"Royal Tropical Institute","class":"OTHER"}},"oversightModule":{"oversightHasDmc":true},"descriptionModule":{"briefSummary":"The purpose of this study is to determine the efficacy of pyronaridine-artesunate and artemether-lumefantrine for the treatment of uncomplicated Plasmodium falciparum malaria in Kenyan children."},"conditionsModule":{"conditions":["Malaria"]},"designModule":{"studyType":"INTERVENTIONAL","phases":["PHASE3"],"designInfo":{"allocation":"RANDOMIZED","interventionModel":"PARALLEL","primaryPurpose":"TREATMENT","maskingInfo":{"masking":"DOUBLE","whoMasked":["INVESTIGATOR","OUTCOMES_ASSESSOR"]}},"enrollmentInfo":{"count":197,"type":"ACTUAL"}},"armsInterventionsModule":{"armGroups":[{"label":"Pyronaridine-artesunate","type":"EXPERIMENTAL","description":"pyronaridine-artesunate: recommended dose according to body weight, once a day for three days.","interventionNames":["Drug: Pyronaridine-artesunate"]},{"label":"Artemether-lumefantrine","type":"ACTIVE_COMPARATOR","description":"artemether-lumefantrine: recommended dose according to body weight, twice a day for three days.","interventionNames":["Drug: Artemether-lumefantrine combination"]}],"interventions":[{"type":"DRUG","name":"Pyronaridine-artesunate","armGroupLabels":["Pyronaridine-artesunate"],"otherNames":["Pyramax"]},{"type":"DRUG","name":"Artemether-lumefantrine combination","armGroupLabels":["Artemether-lumefantrine"],"otherNames":["Coartem"]}]},"outcomesModule":{"primaryOutcomes":[{"measure":"PCR-corrected adequate clinical and parasitological response (ACPR)","timeFrame":"day 28 after initial dose"}],"secondaryOutcomes":[{"measure":"PCR-corrected adequate clinical and parasitological response (ACPR)","timeFrame":"day 42 after initial dose"},{"measure":"crude adequate clinical and parasitological response (ACPR)","timeFrame":"day 28, day 42 after initial dose"},{"measure":"parasite clearance time","timeFrame":"up to 7 days after initial dose"},{"measure":"gametocyte clearance time","timeFrame":"up to 7 days after initial dose"},{"measure":"transmission potential to mosquitos","timeFrame":"day 7 after initial dose"}]},"eligibilityModule":{"eligibilityCriteria":"Inclusion Criteria:

* Children between 6 months and 12 years old, with a body weight of ≥5 kg;
* Living in the catchment area of the study (within a radius of \~10 km from St. Jude's Clinic, Mbita, Kenya);
* Having microscopically confirmed P. falciparum mono-infection (asexual parasite density 1,000-200,000 µL-1).

Exclusion Criteria:

* Signs and symptoms of severe malaria (according to WHO criteria for severe malaria, (WHO 2012)) or any other severe illness necessitating parenteral treatment;
* Mixed Plasmodium infection;
* Clinically suspected (oedema, jaundice and/or ascites) or reported hepatic and/or renal impairment (any cause, as reported by parents/guardians and/or evident from medical history);
* Having anaemia with an Hb \<6 g/dL;
* Evidence of severe malnutrition (severe wasting: z-score weight for age \<-3 and severe stunting: z-score height for age \<-3 (WHO 2009b));
* Having received anti-malarial therapy in the previous two weeks;
* Known history of hypersensitivity, allergic or adverse reactions to artesunate, artemether-lumefantrine or other artemisinins;
* Participating in other anti-malarial drug intervention studies;
* Previous participation in the PAAL study, e.g. in the previous transmission season (each individual child can only take part in this study once);
* Not being available for follow-up.","healthyVolunteers":false,"sex":"ALL","minimumAge":"6 Months","maximumAge":"12 Years","stdAges":["CHILD"]},"contactsLocationsModule":{"overallOfficials":[{"name":"Patrick Sawa, MD, PhD","affiliation":"International Centre of Insect Physiology and Ecology (ICIPE)","role":"PRINCIPAL_INVESTIGATOR"}],"locations":[{"facility":"St. Jude's Clinic, ICIPE","city":"Mbita","zip":"30-40305","country":"Kenya","geoPoint":{"lat":-0.42492,"lon":34.20736}}]},"referencesModule":{"references":[{"pmid":"29866116","type":"DERIVED","citation":"Roth JM, Sawa P, Omweri G, Osoti V, Makio N, Bradley J, Bousema T, Schallig HDFH, Mens PF. Plasmodium falciparum gametocyte dynamics after pyronaridine-artesunate or artemether-lumefantrine treatment. Malar J. 2018 Jun 4;17(1):223. doi: 10.1186/s12936-018-2373-7."},{"pmid":"29764419","type":"DERIVED","citation":"Roth JM, Sawa P, Makio N, Omweri G, Osoti V, Okach S, Choy F, Schallig HDFH, Mens P. Pyronaridine-artesunate and artemether-lumefantrine for the treatment of uncomplicated Plasmodium falciparum malaria in Kenyan children: a randomized controlled non-inferiority trial. Malar J. 2018 May 15;17(1):199. doi: 10.1186/s12936-018-2340-3."}]}},"derivedSection":{"miscInfoModule":{"versionHolder":"2026-11-03"},"conditionBrowseModule":{"meshes":[{"id":"D008288","term":"Malaria"}],"ancestors":[{"id":"D011528","term":"Protozoan Infections"},{"id":"D010272","term":"Parasitic Diseases"},{"id":"D007239","term":"Infections"},{"id":"D000096724","term":"Mosquito-Borne Diseases"},{"id":"D000079426","term":"Vector Borne Diseases"}]},"interventionBrowseModule":{"meshes":[{"id":"C000712628","term":"pyronaridine tetraphosphate, artesunate drug combination"},{"id":"D000077611","term":"Artemether, Lumefantrine Drug Combination"}],"ancestors":[{"id":"D000077549","term":"Artemether"},{"id":"D037621","term":"Artemisinins"},{"id":"D017382","term":"Reactive Oxygen Species"},{"id":"D005609","term":"Free Radicals"},{"id":"D007287","term":"Inorganic Chemicals"},{"id":"D009930","term":"Organic Chemicals"},{"id":"D000078102","term":"Lumefantrine"},{"id":"D005449","term":"Fluorenes"},{"id":"D011084","term":"Polycyclic Aromatic Hydrocarbons"},{"id":"D006841","term":"Hydrocarbons, Aromatic"},{"id":"D006844","term":"Hydrocarbons, Cyclic"},{"id":"D006838","term":"Hydrocarbons"},{"id":"D012717","term":"Sesquiterpenes"},{"id":"D013729","term":"Terpenes"},{"id":"D011083","term":"Polycyclic Compounds"},{"id":"D004338","term":"Drug Combinations"},{"id":"D004364","term":"Pharmaceutical Preparations"}]}},"hasResults":false},
{"protocolSection":{"identificationModule":{"nctId":"NCT02348788","orgStudyIdInfo":{"id":"NMRR91391379918375 ￼"},"organization":{"fullName":"Menzies School of Health Research","class":"OTHER"},"briefTitle":"Artemether-lumefantrine vs Chloroquine for Uncomplicated P. Vivax Malaria in Malaysia","officialTitle":"Artemether-lumefantrine vs Chloroquine in Patients With Acute Non-severe P. Vivax Malaria in Sabah, Malaysia","acronym":"PRIMAL"},"statusModule":{"statusVerifiedDate":"2017-01","overallStatus":"UNKNOWN","lastKnownStatus":"RECRUITING","expandedAccessInfo":{"hasExpandedAccess":false},"startDateStruct":{"date":"2015-01"},"primaryCompletionDateStruct":{"date":"2017-12","type":"ESTIMATED"},"completionDateStruct":{"date":"2017-12","type":"ESTIMATED"},"studyFirstSubmitDate":"2015-01-11","studyFirstSubmitQcDate":"2015-01-22","studyFirstPostDateStruct":{"date":"2015-01-28","type":"ESTIMATED"},"lastUpdateSubmitDate":"2017-01-31","lastUpdatePostDateStruct":{"date":"2017-02-01","type":"ESTIMATED"}},"sponsorCollaboratorsModule":{"responsibleParty":{"type":"SPONSOR"},"leadSponsor":{"name":"Menzies School of Health Research","class":"OTHER"},"collaborators":[{"name":"Ministry of Health, Malaysia","class":"OTHER_GOV"}]},"oversightModule":{"oversightHasDmc":false},"descriptionModule":{"briefSummary":"Both artemether-lumefantrine and chloroquine are currently used and recommended by Malaysian Ministry of Health as blood stage treatments for non-severe P. vivax and P. knowlesi malaria. Microscopic misdiagnosis between Plasmodium species remains a large issue in Sabah, Malaysia and elsewhere. In order to facilitate potential policy change to a unified ACT guideline for all malaria species in Sabah artemether-lumefantrine needs to be evaluated for P. vivax malaria.

Preliminary data in a recently completed RCT evaluating artesunate-mefloquine vs chloroquine for P. vivax showed up to 36% P. vivax recurrence with chloroquine monotherapy by day 28 post treatment without primaquine. Based on these data blood stage chloroquine treatment failure rates should also be evaluated in the context of standard concurrent (rather than delayed) liver stage primaquine dosing, due to both its potential blood stage synergistic effect in addition to known decreased recurrence rates. As artemether-lumefantrine is one of the current first line Ministry of Health ACTs used in Sabah with a lower adverse event profile compared to artesunate-mefloquine, this was recommended as the more appropriate ACT to evaluate against chloroquine.","detailedDescription":"Malaria due to infection with P. vivax is currently estimated at up to 390 million episodes per year worldwide, with substantial morbidity caused by the recurrent nature of its infection, associated anaemia and adverse effects on pregnancy, and ability to cause severe disease and death. The majority of malaria cases from all Plasmodium species in Malaysia are from the Eastern state of Sabah, where despite around a 36-fold reduction in incidence since the implementation of malaria eradication programs in 1961, minimum estimates based on unpublished microscopy data from Sabah State public health records still detailed 8685 malaria cases in 2009-2011. While P. vivax accounts for between 30-50% of these figures currently, studies have demonstrated as overall transmission rates in countries previously endemic for malaria decline the proportion of cases attributable to P. vivax increases. Mixed P. falciparum / P. vivax infections are also likely to be underestimated in areas of co-endemicity, with high rates of recurrence of P. vivax shown in studies following treatment for apparent P. falciparum mono-infection or mixed Plasmodium spp. infections.

Malaysian Ministry of Health guidelines currently recommends chloroquine and primaquine as first line treatment for the erythrocytic and hypnozoite life stages of uncomplicated P. vivax malaria respectively. While resistance to chloroquine has previously been documented in Sabah and also Peninsular Malaysia, the unstable transmission dynamics and recent reduction in P. vivax incidence due to public health measures mean the current risk of chloroquine-resistant P.vivax transmission is likely to be low. Despite this, due to documented increasing resistance in surrounding countries including Indonesia, Thailand, Vietnam, and PNG, transient populations of migrant workers, and recent concerns of the failing efficacy of hypnozoite eradication by primaquine, the need for ongoing therapeutic efficacy monitoring is recommended.

There is also growing support for artemisinin-based combination therapy (ACT) as a unified first line treatment choice in areas co-endemic for P. falciparum and P. vivax, as adopted by a small number of countries including PNG, Solomon Islands, Vanuatu and Papua, Indonesia, due to the regional increase of chloroquine-resistant P. vivax, and ongoing concerns over the microscopic misdiagnosis of Plasmodium species. This is also particularly relevant for P. knowlesi malaria, as it is frequently misidentified on microscopy as P. falciparum and P. malariae due to morphological similarities in the early trophozoite, and late trophozoite and schizont life stages respectively, with studies showing up to 80% of P. malariae and 7-12% of P. falciparum in this region are actually P. knowlesi when definitively evaluated with PCR. Misdiagnosis has concerning treatment implications, as although P. knowlesi has been shown to respond well to ACT and chloroquine, unlike P. malariae, knowlesi malaria has a rapid 24-hour replication rate and can cause hyperparasitaemia, severe complications and fatal outcomes, while the inadvertent use of chloroquine for widely chloroquine-resistant P. falciparum may also have fatal consequences.

Previous reluctance to use ACTs in presumed chloroquine-sensitive P.vivax areas were centered on concerns over efficacy and cost. The advent of generically produced ACTs is improving cost-related issues, while a recent Cochrane review of clinical trials looking at the use of ACT versus chloroquine for uncomplicated vivax malaria showed that ACTs are equivalent to chloroquine in preventing recurrent parasitaemia in the first 28 days (RR 1, 95% CI 0.30 to 3.39), and those with long half lives such as mefloquine or piperaquine are superior over a 6-8 week follow up, with fewer recurrent episodes after day 28 (RR 0.47, 95% CI 0.29 to 0.76). This post treatment prophylaxis benefit of longer acting agents extends to the reduction in gametocyte carriage, delay in relapse or re-infection and decreased risk of anaemia development, all of which contribute to decreased transmissibility and health care cost."},"conditionsModule":{"conditions":["Plasmodium Vivax Malaria Without Complication"],"keywords":["Vivax","Malaria","artemether-lumefantrine","chloroquine","RCT"]},"designModule":{"studyType":"INTERVENTIONAL","phases":["PHASE3"],"designInfo":{"allocation":"RANDOMIZED","interventionModel":"PARALLEL","primaryPurpose":"TREATMENT","maskingInfo":{"masking":"NONE"}},"enrollmentInfo":{"count":98,"type":"ESTIMATED"}},"armsInterventionsModule":{"armGroups":[{"label":"Artemether-lumefantrine + Primaquine","type":"ACTIVE_COMPARATOR","description":"1 tablet = 20mg artemether and 120mg lumefantrine. Dosing at 0, 8, 24, 36, 48 and 60 hours. Dose according to bodyweight; \>35kg = 2 tablets, 26-35kg = 3 tablets, 16-25kg = 2 tablets, \>10-15kg = 1 tablet.

Primaquine = 7.5mg tablet. Dosing daily for 14 days from Day 0. Dose according to bodyweight; \>35kg = 30mg, \<35kg = 0.5mg/kg","interventionNames":["Drug: Artemether-lumefantrine + Primaquine"]},{"label":"Chloroquine + Primaquine","type":"ACTIVE_COMPARATOR","description":"1 tablet contains 155mg chloroquine base. Adult dose (\>35kg); 620mg (4 tablets) at 0 hours, and 310mg (2 tablets) at 6-8, 24 and 48 hours.

Child dose (\>10-35kg); 10mg/kg at 0 hours, and 5mg/kg at 6-8, 24 and 48 hours. Primaquine = 7.5mg tablet. Dosing daily for 14 days from Day 0. Dose according to bodyweight; \>35kg = 30mg, 10-35kg = 0.5mg/kg","interventionNames":["Drug: Chloroquine + Primaquine"]}],"interventions":[{"type":"DRUG","name":"Artemether-lumefantrine + Primaquine","armGroupLabels":["Artemether-lumefantrine + Primaquine"]},{"type":"DRUG","name":"Chloroquine + Primaquine","armGroupLabels":["Chloroquine + Primaquine"]}]},"outcomesModule":{"primaryOutcomes":[{"measure":"Parasite clearance at 48 hours","description":"The difference in proportion of patients with negative microscopy for P. vivax asexual parasites at 48 hours after treatment with A-L compared to CQ.","timeFrame":"48 hours"}],"secondaryOutcomes":[{"measure":"Parasite clearance time in hours","description":"The difference in absolute time in hours post treatment to microscopic parasite clearance between treatment arms","timeFrame":"Within 72 hours post treatment"},{"measure":"Parasite clearance at day 1 and day 3","description":"The difference in proportion of patients with negative microscopy for P. vivax asexual parasites at 24 and 72 hours between treatment arms","timeFrame":"At 24 and 72 hours post treatment"},{"measure":"Treatment outcome","description":"Early treatment failure (ETF), late treatment failure (LTF), and adequate parasitological and clinical response (APCR) at day 28 and day 42","timeFrame":"Day 28 and 42 post treatment"},{"measure":"Risk of anaemia","description":"Proportion with haemoglobin less than 12 g/dL in women or less than 13 g/dL in men between treatment arms","timeFrame":"Day 28 post treatment"},{"measure":"Fractional fall in haemoglobin at day 3","description":"Difference in fractional fall in haemoglobin concentration between treatment arms 3 days post treatment","timeFrame":"Day 3 post treatment"},{"measure":"Haemoglobin nadir","description":"Difference in risk of lowest recorded haemoglobin concentration between treatment arms during 42 day follow-up","timeFrame":"42 days post treatment"},{"measure":"Risk of P. vivax gametocyte carriage during follow up","description":"The difference in proportion of microscopic P. vivax gametocyte carriage between treatment arms during 42 day follow up","timeFrame":"42 days"},{"measure":"Risk of adverse events","description":"Risk of adverse events (AE) and serious adverse events (SAE) including relationship to study drugs throughout follow up","timeFrame":"42 days"},{"measure":"Length of hospital inpatient stay","description":"Number of days post enrolment requiring admission until treatment completed and 2 negative blood slides for malaria allowing discharge as per Malaysian Ministry of Health guidelines","timeFrame":"From 2-9 days post enrolment"}]},"eligibilityModule":{"eligibilityCriteria":"Inclusion Criteria:

* Male and female patients at least 1 year of age and weighing more than 10kg
* Microscopic diagnosis of P. vivax monoinfection
* Negative P. falciparum malaria rapid diagnostic test (histidine-rich-protein 2)
* Fever (temperature ≥37.5°C) or history of fever in the last 48 hours
* Written informed consent to participate in trial

Exclusion Criteria:

* Clinical or laboratory criteria for severe malaria, including warning signs, according to modified WHO 2010 criteria
* Parasitaemia \> 100,000 /μL
* Pregnancy or lactation
* Known hypersensitivity or allergy to study drugs
* Serious underlying disease (cardiac, renal or hepatic)
* Received anti-malarials in previous 2 months
* History of psychiatric illness, epilepsy, or cerebral malaria","healthyVolunteers":false,"sex":"ALL","minimumAge":"1 Year","stdAges":["CHILD","ADULT","OLDER_ADULT"]},"contactsLocationsModule":{"centralContacts":[{"name":"Matthew Grigg, MBBS","role":"CONTACT","phone":"+60149569476","email":"mat_grigg@hotmail.com"}],"overallOfficials":[{"name":"Timothy William, MBBS, FRCP","affiliation":"Ministry of Health, Malaysia","role":"PRINCIPAL_INVESTIGATOR"}],"locations":[{"facility":"Kota Marudu District Hospital","status":"RECRUITING","city":"Kota Marudu","state":"Sabah","country":"Malaysia","contacts":[{"name":"Matthew Grigg, MBBS","role":"CONTACT","phone":"+60149569476","email":"mat_grigg@hotmail.com"},{"name":"Timothy William, MBBS","role":"PRINCIPAL_INVESTIGATOR"},{"name":"Tsin W Yeo, MBBS","role":"SUB_INVESTIGATOR"},{"name":"Nicholas M Anstey, MBBS","role":"SUB_INVESTIGATOR"},{"name":"Bridget E Barber, MBBS","role":"SUB_INVESTIGATOR"},{"name":"Jayaram Menon, MBBS","role":"SUB_INVESTIGATOR"},{"name":"Ric N Price, MBBS","role":"SUB_INVESTIGATOR"},{"name":"Matthew J Grigg, MBBS","role":"SUB_INVESTIGATOR"}]},{"facility":"Kudat District Hospital","status":"RECRUITING","city":"Kudat","state":"Sabah","country":"Malaysia","contacts":[{"name":"Matthew Grigg, MBBS","role":"CONTACT","phone":"+60149569476","email":"mat_grigg@hotmail.com"},{"name":"Tsin W Yeo, MBBS","role":"SUB_INVESTIGATOR"},{"name":"Nicholas M Anstey, MBBS","role":"SUB_INVESTIGATOR"},{"name":"Bridget E Barber, MBBS","role":"SUB_INVESTIGATOR"},{"name":"Prabakaran Dhanaraj, MBBS","role":"SUB_INVESTIGATOR"},{"name":"Jayaram Menon, MBBS","role":"SUB_INVESTIGATOR"},{"name":"Ric N Price, MBBS","role":"SUB_INVESTIGATOR"},{"name":"Timothy William, MBBS","role":"PRINCIPAL_INVESTIGATOR"},{"name":"Matthew J Grigg, MBBS","role":"SUB_INVESTIGATOR"}],"geoPoint":{"lat":6.88732,"lon":116.82364}},{"facility":"Pitas District Hospital","status":"RECRUITING","city":"Pitas","state":"Sabah","country":"Malaysia","contacts":[{"name":"Matthew Grigg, MBBS","role":"CONTACT","phone":"+60149569476","email":"mat_grigg@hotmail.com"},{"name":"Timothy William, MBBS","role":"PRINCIPAL_INVESTIGATOR"},{"name":"Tsin W Yeo, MBBS","role":"SUB_INVESTIGATOR"},{"name":"Nicholas M Anstey, MBBS","role":"SUB_INVESTIGATOR"},{"name":"Bridget E Barber, MBBS","role":"SUB_INVESTIGATOR"},{"name":"Jayaram Menon, MBBS","role":"SUB_INVESTIGATOR"},{"name":"Ric N Price, MBBS","role":"SUB_INVESTIGATOR"},{"name":"Matthew J Grigg, MBBS","role":"SUB_INVESTIGATOR"}],"geoPoint":{"lat":6.72779,"lon":117.05779}}]},"ipdSharingStatementModule":{"ipdSharing":"UNDECIDED"}},"derivedSection":{"miscInfoModule":{"versionHolder":"2026-11-03"},"conditionBrowseModule":{"meshes":[{"id":"D008288","term":"Malaria"}],"ancestors":[{"id":"D011528","term":"Protozoan Infections"},{"id":"D010272","term":"Parasitic Diseases"},{"id":"D007239","term":"Infections"},{"id":"D000096724","term":"Mosquito-Borne Diseases"},{"id":"D000079426","term":"Vector Borne Diseases"}]},"interventionBrowseModule":{"meshes":[{"id":"D000077611","term":"Artemether, Lumefantrine Drug Combination"},{"id":"D011319","term":"Primaquine"},{"id":"D002738","term":"Chloroquine"}],"ancestors":[{"id":"D000077549","term":"Artemether"},{"id":"D037621","term":"Artemisinins"},{"id":"D017382","term":"Reactive Oxygen Species"},{"id":"D005609","term":"Free Radicals"},{"id":"D007287","term":"Inorganic Chemicals"},{"id":"D009930","term":"Organic Chemicals"},{"id":"D000078102","term":"Lumefantrine"},{"id":"D005449","term":"Fluorenes"},{"id":"D011084","term":"Polycyclic Aromatic Hydrocarbons"},{"id":"D006841","term":"Hydrocarbons, Aromatic"},{"id":"D006844","term":"Hydrocarbons, Cyclic"},{"id":"D006838","term":"Hydrocarbons"},{"id":"D012717","term":"Sesquiterpenes"},{"id":"D013729","term":"Terpenes"},{"id":"D011083","term":"Polycyclic Compounds"},{"id":"D004338","term":"Drug Combinations"},{"id":"D004364","term":"Pharmaceutical Preparations"},{"id":"D000634","term":"Aminoquinolines"},{"id":"D011804","term":"Quinolines"},{"id":"D006574","term":"Heterocyclic Compounds, 2-Ring"},{"id":"D000072471","term":"Heterocyclic Compounds, Fused-Ring"},{"id":"D006571","term":"Heterocyclic Compounds"}]}},"hasResults":false},
{"protocolSection":{"identificationModule":{"nctId":"NCT02698748","orgStudyIdInfo":{"id":"CNBS (173/CNBS/13)"},"organization":{"fullName":"Centro de Investigacao em Saude de Manhica","class":"OTHER"},"briefTitle":"Evaluating the Role of Chloroquine for Malaria Elimination","officialTitle":"Evaluating the Potential Role of Chloroquine in Preventing Infections During Elimination Campaigns: A Randomized, Single-blind, Placebo-controlled Trial in Asymptomatic Mozambican Adults","acronym":"Cloroquina"},"statusModule":{"statusVerifiedDate":"2016-02","overallStatus":"COMPLETED","expandedAccessInfo":{"hasExpandedAccess":false},"startDateStruct":{"date":"2015-01"},"primaryCompletionDateStruct":{"date":"2015-04","type":"ACTUAL"},"completionDateStruct":{"date":"2015-06","type":"ACTUAL"},"studyFirstSubmitDate":"2015-01-13","studyFirstSubmitQcDate":"2016-02-29","studyFirstPostDateStruct":{"date":"2016-03-04","type":"ESTIMATED"},"lastUpdateSubmitDate":"2018-02-06","lastUpdatePostDateStruct":{"date":"2018-02-07","type":"ACTUAL"}},"sponsorCollaboratorsModule":{"responsibleParty":{"type":"SPONSOR"},"leadSponsor":{"name":"Centro de Investigacao em Saude de Manhica","class":"OTHER"}},"oversightModule":{"oversightHasDmc":false},"descriptionModule":{"briefSummary":"One of the proposed ideas for malaria elimination includes the use of drugs to interrupt malaria transmission by exhausting the human reservoir of infection. Theoretically, mass treatment of an entire population with a very effective and rapid-acting drug (for instance an ACT), followed by the administration of an effective prophylactic regime during a minimum of four weeks, so as to outlast the typical development period of Plasmodium parasites in Anopheline mosquitoes, could achieve the same objective. In this respect, chloroquine (CQ) would be an appropriate candidate. This drug exhibits two conditions that make it attractive for elimination campaigns: 1) It has been demonstrated to have an excellent safety profile, allowing for its use in all age groups including pregnant women and children; and 2) Its relatively long elimination half life (t1/2=1-2 months) can provide a long post-treatment prophylactic effect. Recent evidence suggests that CQ sensitivity may be returning in places where discontinuation has reduced the drug pressure to the parasite populations. In countries such as Malawi, P. falciparum seems to have regained full sensitivity to CQ, and molecular markers of antiCQ resistance have nearly disappeared. While this does not support the reintroduction of CQ as first line therapy, it does suggest that, if proven sensitive in a given area, it could play a prophylactic role in malaria elimination strategies when used in combination with other drugs or tools. Thus, we intend to evaluate the potential role of chloroquine in preventing infections during elimination campaigns by performing a randomized, single-blind, placebo-controlled trial in asymptomatic Mozambican adults.

Choosing asymptomatic parasitaemic adult males from a malaria-endemic area as our study population introduces limited risks when administering a drug with an uncertain efficacy (47% efficacious in 2001-2002). In malaria-endemic areas, this age group has a remarkably low risk of developing severe disease (irrespective of clinical symptoms), and it is foreseeable that parasitemia may be well tolerated, and in certain cases, spontaneously cleared from the individual's blood as a result of the immune system. In the unlikely event of any clinical symptomatology appearing throughout the follow-up, individuals will be examined by a study clinician and treated immediately with the country's first-line malaria treatment (artemether-lumefantrine, Coartem ®).","detailedDescription":"This surveillance study is a two-arm prospective evaluation of parasitological responses to directly observed treatment with CQ (vs. placebo) for the clearing of asymptomatic parasitemia. People with asymptomatic P. falciparum parasitaemia, defined as the presence of a P. falciparum infection in the absence of any clinical symptomatology including fever, history of fever in the preceding 24 hours, malaise, fatigue, chills, or any other symptoms that may be derived from the malarial infection, who meet the study inclusion criteria will be enrolled, treated on site with CQ phosphate (25mg/Kg CQ base divided in three daily doses: 10mg/kg day 1 (usually 4 tablets); 10mg/kg day 2 (4 tablets) and 5mg/kg day 3 (2 tablets)) or placebo pills (same schedule, 4 tablets day one and two; and 2 tablets on day three), and monitored for 28 days. The follow-up will consist of a fixed schedule of check-up visits and corresponding clinical and laboratory examinations. On the basis of the results of these assessments, the patients will be classified as having therapeutic failure (early or late) or an adequate response. The proportion of patients experiencing therapeutic failure during the follow-up period will be used to estimate the efficacy of the study drug. PCR analysis will be used to distinguish between a true recrudescence due to treatment failure and episodes of reinfection."},"conditionsModule":{"conditions":["Malaria"],"keywords":["Chloroquine","Malaria Elimination","P.falciparum","Clinical Trial","Mozambique","Adults"]},"designModule":{"studyType":"INTERVENTIONAL","phases":["PHASE2","PHASE3"],"designInfo":{"allocation":"RANDOMIZED","interventionModel":"PARALLEL","primaryPurpose":"PREVENTION","maskingInfo":{"masking":"SINGLE","whoMasked":["PARTICIPANT"]}},"enrollmentInfo":{"count":75,"type":"ACTUAL"}},"armsInterventionsModule":{"armGroups":[{"label":"Chloroquine","type":"EXPERIMENTAL","description":"Chloroquine sulphate (Meriquine®; 250mg; 150 mg of chloroquine base; Baroda, India) will be administered at a total dose of 25 mg/kg (expressed as mg of CQ base per kg body weight, once daily during 3 consecutive days, following the schedule 10mg/kg Day 1; 10mg/kg day 2 and 5 mg/kg day 3).","interventionNames":["Drug: Chloroquine"]},{"label":"Placebo","type":"PLACEBO_COMPARATOR","description":"Placebo pills will be standard placebo capsules filled with powder contents with no pharmaceutical activity. They will not be identical to the chloroquine tablets, so the study will not be double blind, but rather single blinded. Placebo tablets will be manufactured by the pharmaceutical department of the Hospital Clínic, in Barcelona, Spain.","interventionNames":["Drug: Placebo"]}],"interventions":[{"type":"DRUG","name":"Chloroquine","description":"Chloroquine sulphate (Meriquine®; 250mg; 150 mg of chloroquine base; Baroda, India) will be administered at a total dose of 25 mg/kg (expressed as mg of CQ base per kg body weight, once daily during 3 consecutive days, following the schedule 10mg/kg Day 1; 10mg/kg day 2 and 5 mg/kg day 3).","armGroupLabels":["Chloroquine"],"otherNames":["Chloroquine Phosphate"]},{"type":"DRUG","name":"Placebo","description":"Placebo Placebo pills will be standard placebo capsules filled with powder contents with no pharmaceutical activity. They will not be identical to the chloroquine tablets, so the study will not be double blind, but rather single blinded. Placebo tablets will be manufactured by the pharmaceutical department of the Hospital Clínic, in Barcelona, Spain","armGroupLabels":["Placebo"],"otherNames":["Placebo capsules"]}]},"outcomesModule":{"primaryOutcomes":[{"measure":"Adequate parasitologic response (APR) to therapy","description":"the absence of parasitemia at the end of the trial's follow-up period (Day 28), regardless of axillary temperature, without having previously met any of the criteria for early and late treatment failure","timeFrame":"28 days after first day of drug intake"}],"secondaryOutcomes":[{"measure":"Early parasitologic failure","description":"Detection of parasites once the initial parasitemia has been cleared in the time period from day 1 to day 3 after first day of drug intake","timeFrame":"1-3 days after first day of drug intake"},{"measure":"Late parasitologic failure","description":"The detection of parasites in patients having cleared their initial parasitemia anytime from day 4 to day 28","timeFrame":"4-28 days after first day of drug intake"},{"measure":"Prevalence of chloroquine conferring pfcrt K76T mutation in pre-treatment infections","description":"Proportion of the isolates detected with this specific mutation among isolates at baseline (before study drug initiation)","timeFrame":"0 days after first day of drug intake"},{"measure":"Rates of pre treatment pfcrt K76T mutation in cases of chloroquine treatment failure","description":"Proportion of the isolates detected with this specific mutation at baseline among cases with confirmed treatment failure those","timeFrame":"0 days after first day of drug intake"},{"measure":"Rates of post treatment pfcrt K76T mutation in cases of chloroquine treatment failure","description":"Proportion of the isolates detected as new infections or recrudescent ones with this specific mutation","timeFrame":"28 days after first day of drug intake"},{"measure":"Clearance time of parasitaemia","description":"time in hours until the clearance of parasitemia","timeFrame":"28 days after first day of drug intake"}]},"eligibilityModule":{"eligibilityCriteria":"Inclusion Criteria:

* Male individuals
* P. falciparum infection detected by microscopy (Minimum 250 parasites/microliter; Maximum 10.000parasites/microliter)
* Ability to swallow oral medication
* Ability and willingness to comply with the study protocol for the duration of the study and to comply with the study visit schedule; and
* Informed consent from the participant individual

Exclusion Criteria:

* Age \<18 years
* Female individuals
* Axillary temperature \>=37.5ºC
* Presence of any other co-existing clinical condition that in the opinion of the recruiting physician would not allow the individual to be considered a "healthy" asymptomatic carrier
* Regular medication which may interfere with antimalarial efficacy or antimalarial pharmacokinetics, such as Cotrimoxazole
* History of hypersensitivity reactions or contraindications to CQ
* Known HIV positive patients in treatment with antiretrovirals","healthyVolunteers":false,"sex":"MALE","minimumAge":"18 Years","stdAges":["ADULT","OLDER_ADULT"]},"contactsLocationsModule":{"overallOfficials":[{"name":"Pedro Aide, MD, MSc, PhD","affiliation":"Centro de Investigação em Saude de Manhiça","role":"PRINCIPAL_INVESTIGATOR"}],"locations":[{"facility":"Centro de Investigaçao em Saude de Manhiça","city":"Manhiça","state":"Maputo Province","zip":"1902","country":"Mozambique","geoPoint":{"lat":-25.40222,"lon":32.80722}}]},"referencesModule":{"references":[{"pmid":"29546346","type":"DERIVED","citation":"Galatas B, Marti-Soler H, Nhamussua L, Cistero P, Aide P, Saute F, Menendez C, Rabinovich NR, Alonso PL, Bassat Q, Mayor A. Dynamics of Afebrile Plasmodium falciparum Infections in Mozambican Men. Clin Infect Dis. 2018 Sep 14;67(7):1045-1052. doi: 10.1093/cid/ciy219."},{"pmid":"28465550","type":"DERIVED","citation":"Galatas B, Nhamussua L, Candrinho B, Mabote L, Cistero P, Gupta H, Rabinovich R, Menendez C, Macete E, Saute F, Mayor A, Alonso P, Bassat Q, Aide P. In-Vivo Efficacy of Chloroquine to Clear Asymptomatic Infections in Mozambican Adults: A Randomized, Placebo-controlled Trial with Implications for Elimination Strategies. Sci Rep. 2017 May 2;7(1):1356. doi: 10.1038/s41598-017-01365-4."}]},"ipdSharingStatementModule":{"ipdSharing":"UNDECIDED"}},"derivedSection":{"miscInfoModule":{"versionHolder":"2026-11-03"},"conditionBrowseModule":{"meshes":[{"id":"D008288","term":"Malaria"}],"ancestors":[{"id":"D011528","term":"Protozoan Infections"},{"id":"D010272","term":"Parasitic Diseases"},{"id":"D007239","term":"Infections"},{"id":"D000096724","term":"Mosquito-Borne Diseases"},{"id":"D000079426","term":"Vector Borne Diseases"}]},"interventionBrowseModule":{"meshes":[{"id":"D002738","term":"Chloroquine"},{"id":"C023676","term":"chloroquine diphosphate"}],"ancestors":[{"id":"D000634","term":"Aminoquinolines"},{"id":"D011804","term":"Quinolines"},{"id":"D006574","term":"Heterocyclic Compounds, 2-Ring"},{"id":"D000072471","term":"Heterocyclic Compounds, Fused-Ring"},{"id":"D006571","term":"Heterocyclic Compounds"}]}},"hasResults":false},
{"protocolSection":{"identificationModule":{"nctId":"NCT02216123","orgStudyIdInfo":{"id":"116564"},"organization":{"fullName":"GlaxoSmithKline","class":"INDUSTRY"},"briefTitle":"Study to Assess the Incidence of Hemolysis, Safety, and Efficacy of Tafenoquine (SB-252263, WR238605) Versus Primaquine in Subjects With Plasmodium Vivax Malaria","officialTitle":"A Randomized, Double-Blind, Double Dummy, Comparative, Multicenter Study to Assess the Incidence of Hemolysis, Safety, and Efficacy of Tafenoquine (SB-252263, WR238605) Versus Primaquine in the Treatment of Subjects With Plasmodium Vivax Malaria"},"statusModule":{"statusVerifiedDate":"2018-02","overallStatus":"COMPLETED","expandedAccessInfo":{"hasExpandedAccess":false},"startDateStruct":{"date":"2015-04-30","type":"ACTUAL"},"primaryCompletionDateStruct":{"date":"2016-11-04","type":"ACTUAL"},"completionDateStruct":{"date":"2016-11-04","type":"ACTUAL"},"studyFirstSubmitDate":"2014-06-19","studyFirstSubmitQcDate":"2014-08-11","studyFirstPostDateStruct":{"date":"2014-08-13","type":"ESTIMATED"},"resultsFirstSubmitDate":"2017-11-01","resultsFirstSubmitQcDate":"2018-04-17","resultsFirstPostDateStruct":{"date":"2018-05-16","type":"ACTUAL"},"lastUpdateSubmitDate":"2018-04-17","lastUpdatePostDateStruct":{"date":"2018-05-16","type":"ACTUAL"}},"sponsorCollaboratorsModule":{"responsibleParty":{"type":"SPONSOR"},"leadSponsor":{"name":"GlaxoSmithKline","class":"INDUSTRY"},"collaborators":[{"name":"Medicines for Malaria Venture","class":"OTHER"}]},"oversightModule":{"oversightHasDmc":true},"descriptionModule":{"briefSummary":"This is a prospective, double-blind, double-dummy, multicenter, comparative study. A total of 300 subjects will be randomized to treatment on Day 1, of which a minimum of 50 female subjects must be enrolled that display moderate glucose-6-phosphate dehydrogenase (G6PD) deficiency (\>=40% - \<70% of the site median G6PD value). Subjects must have a blood smear that is positive for P. vivax at entry. Subjects will be randomized 2:1 to receive tafenoquine (TQ)/chloroquine(CQ) or the active comparator primaquine (PQ)/CQ. All subjects will receive CQ on Days 1 to 3, followed by TQ or PQ and matching placebo beginning on Day 1 or 2. Tafenoquine, or matching placebo, will be given as a single, 300mg dose. Subjects will receive PQ (15mg once daily) or matching placebo for 14 days. The duration of the study is 180 days, including screening and randomization to treatment (Day 1), three in-hospital days (Days 1-3), four out-patient visits while on treatment with study medication (Days 5, 8, 11 and 15) and seven follow-up visits (Days 22, 29, 60, 90, 120, 150 and 180).

The primary safety data collected in this study will help to understand the hemolysis risk to both G6PD-normal and G6PD-deficient subjects. The efficacy data produced from this study will support the results for sister study TAF112582, the pivotal phase III efficacy and safety study of the TQ program."},"conditionsModule":{"conditions":["Malaria, Vivax"],"keywords":["Tafenoquine","Plasmodium vivax","Hemolysis","Primaquine","Chloroquine","Glucose-6-phosphate dehydrogenase (G6PD)","Relapse"]},"designModule":{"studyType":"INTERVENTIONAL","phases":["PHASE3"],"designInfo":{"allocation":"RANDOMIZED","interventionModel":"PARALLEL","primaryPurpose":"TREATMENT","maskingInfo":{"masking":"DOUBLE","whoMasked":["PARTICIPANT","INVESTIGATOR"]}},"enrollmentInfo":{"count":251,"type":"ACTUAL"}},"armsInterventionsModule":{"armGroups":[{"label":"Tafenoquine+ Chloroquine","type":"EXPERIMENTAL","description":"All subjects will receive one of two formulations of CQ from Days 1 to 3 (600 mg \[2×CQ 300 mg\] on Day 1, 600 mg on Day 2 and 300 mg on Day 3, each once daily \[OD\] orally; OR, 620 mg \[4×CQ 155 mg\] on Day 1, 620 mg on Day 2 and 310 mg on Day 3, each once daily \[OD\] orally). Tafenoquine 300mg (2×TQ 150 mg) will be given as a single oral dose on Day 1 or Day 2. Primaquine matching placebo will be given OD orally beginning on Day 1 or Day 2 and continue for 14 days total dosing. All subjects will be followed-up till 180 days.","interventionNames":["Drug: Tafenoquine","Drug: Chloroquine","Drug: Primaquine Placebo"]},{"label":"Primaquine+ Chloroquine","type":"EXPERIMENTAL","description":"All subjects will receive one of two formulations of CQ from Days 1 to 3 (600 mg \[2×CQ 300 mg\] on Day 1, 600 mg on Day 2 and 300 mg on Day 3, each once daily \[OD\] orally; OR, 620 mg \[4×CQ 155 mg\] on Day 1, 620 mg on Day 2 and 310 mg on Day 3, each once daily \[OD\] orally). Primaquine 15mg will be given OD orally beginning on Day 1 or Day 2 and continue for 14 total dosing. Tafenoquine matching placebo will be given as a single oral dose on Day 1 or Day 2. All subjects will be followed-up till 180 days.","interventionNames":["Drug: Tafenoquine Placebo","Drug: Chloroquine","Drug: Primaquine"]}],"interventions":[{"type":"DRUG","name":"Tafenoquine","description":"Tafenoquine will be supplied as a dark pink, capsule-shaped, film-coated tablet that is plain on both sides. Each tablet will contain 150mg TQ.","armGroupLabels":["Tafenoquine+ Chloroquine"]},{"type":"DRUG","name":"Tafenoquine Placebo","description":"Placebo TQ tablets will be supplied as a dark pink, capsule-shaped, film-coated tablet that is plain on both sides, with common excipients of appropriate quality.","armGroupLabels":["Primaquine+ Chloroquine"]},{"type":"DRUG","name":"Chloroquine","description":"One of two formulations of commercially available generic chloroquine may be utilized in this study:

1. tablets containing 500 mg chloroquine phosphate (equivalent to 300 mg chloroquine free base); or,
2. tablets containing 250 mg chloroquine phosphate (equivalent to 155 mg chloroquine free base).","armGroupLabels":["Primaquine+ Chloroquine","Tafenoquine+ Chloroquine"]},{"type":"DRUG","name":"Primaquine","description":"Commercially available primaquine containing primaquine phosphate united states pharmacopeia (USP), 26.3 mg (equivalent to primaquine base 15 mg) will be utilized in this study. Primaquine, a pink film-coated tablet imprinted W on one side and P97 on the other side. The PQ tablets for this study have been over-encapsulated in a Swedish orange size B supro capsule.","armGroupLabels":["Primaquine+ Chloroquine"]},{"type":"DRUG","name":"Primaquine Placebo","description":"Placebo to match PQ will be supplied as Swedish orange size B supro capsules with common excipients of appropriate quality.","armGroupLabels":["Tafenoquine+ Chloroquine"]}]},"outcomesModule":{"primaryOutcomes":[{"measure":"Percentage of Participants With Clinically Relevant Hemolysis.","description":"Clinically relevant hemolysis is defined as a decrease in hemoglobin of \>=30% or \>3 grams per deciliter (g/dL) from Baseline; or, an overall drop in hemoglobin below 6.0 g/dL at any visit after the first dose of study medication. The percentage of participants with clinically relevant hemolysis has been summarized. Safety Population comprised of all randomized participants who received at least one dose of blinded study medication.","timeFrame":"Up to Day 180"},{"measure":"Percentage of Female Participants With Moderate Glucose-6 Phosphate Dehydrogenase (G6PD) Deficiency Experiencing Clinically Relevant Hemolysis.","description":"Clinically relevant hemolysis is defined as a decrease in hemoglobin of \>=30% or \>3 g/dL from Baseline; or, an overall drop in hemoglobin below 6.0 g/dL at any visit after the first dose of study medication. Despite additional efforts, no females with moderate G6PD-deficiency were enrolled that experienced clinically-significant hemolysis during the study; hence, the end point could not be estimated.","timeFrame":"Up to Day 180"}],"secondaryOutcomes":[{"measure":"Rate of Relapse-free Efficacy at Six Months Post Dose","description":"A participant was considered to have demonstrated relapse-free efficacy at 6 months if: a) Participant had non-zero P. vivax asexual parasite count at Baseline. b) Participant showed initial clearance of P. vivax parasitemia defined as two negative asexual P. vivax parasite counts, with at least 6 hours between the counts, and no positive counts in the interval. c) Participant had no positive asexual P. vivax parasite count at any assessment prior to or on Study Day 201 following initial parasite clearance. d) Participant did not take a concomitant medication with anti-malarial activity at any point between Study Day 1 and their last parasite assessment. e) Participant is parasite-free at 6 months. The rate of relapse-free efficacy was estimated by Kaplan-Meier methodology. The percentage of participants who were relapse-free at 6 months post dose has been presented along with 95% confidence interval.","timeFrame":"6 months post dose"},{"measure":"Rate of Relapse-free Efficacy at Four Months Post Dose","description":"A participant was considered to have demonstrated recurrence-free efficacy at 4 months if: a) Participant had non-zero P. vivax asexual parasite count at Baseline. b) Participant showed initial clearance of P. vivax parasitemia. c) Participant had no positive asexual P. vivax parasite count at any assessment prior to or on Study Day 130 following initial parasite clearance. d) Participant did not take a concomitant medication with anti-malarial activity at any point between Study Day 1 and their last parasite assessment after Study Day 109 (up to and including Study Day 130). e) Participant is parasite-free at 4 months. The rate of relapse-free efficacy was estimated by Kaplan-Meier methodology. The percentage of participants who were relapse-free at 4 months post dose has been presented along with 95% confidence interval.","timeFrame":"4 months post dose"},{"measure":"Time to Relapse of P. Vivax Malaria","description":"Relapse is defined by a positive blood smear with or without vivax symptoms. Relapse is described as any recurrence of malaria that occurred after Day 32 of the study. The time to relapse was analyzed by the Kaplan-Meier method. The median number of days to relapse along with 95% confidence interval has been presented for each treatment group.","timeFrame":"Up to Day 180"},{"measure":"Time to Parasite Clearance","description":"Parasite clearance time is defined as time needed to clear asexual parasite from the blood that is, parasite numbers falling below the limit of detection in the thick blood smear and remaining undetectable after 6 to 12 hours later. The time to achieve parasite clearance was analyzed by Kaplan-Meier methodology. The median parasite clearance time along with 95% confidence interval has been presented for each treatment group.","timeFrame":"Up to Day 180"},{"measure":"Time to Fever Clearance","description":"Fever clearance time is defined as the time from first dose of treatment to the time when body temperature falls to normal within Study Days 1-4 and remains normal for at least 48 hours up to the Day 8 visit. Fever clearance was considered to have been achieved once an initial temperature of more than 37.4 degree Celsius is reduced to a value less than or equal to 37.4 degree Celsius, in the absence of value more than 37.4 degree Celsius in the following 48 hours up to the Day 8 visit. The time taken to achieve fever clearance was analyzed by Kaplan-Meier method.","timeFrame":"Up to Day 9"},{"measure":"Time to Gametocyte Clearance","description":"Gametocyte clearance time is defined as time from first dose until the first slide that was gametocyte negative and remained so at the next slide reading. The time taken to achieve gametocyte clearance was analyzed by Kaplan-Meier method.","timeFrame":"Up to Day 180"},{"measure":"Number of Participants With Recrudescence","description":"Recrudescence is defined as any P. vivax parasitemia occurring on or before Day 32 (that is, blood stage treatment failure). A participant was considered to have had a recrudescence if both of the following were true: a) Participant had a positive P. vivax asexual parasite count at Baseline and demonstrated clearance (that is, did not have two negative asexual P. vivax parasite counts, with at least 6 hours between the counts, and no positive counts in the interval). b) Participant had a positive genetically homologous asexual P. vivax parasite count, after their zero count in Days 1 to 5, but on or before Study Day 32. The number of participants with recrudescence before Study Day 33 has been presented.","timeFrame":"Up to Day 32"},{"measure":"Number of Participants With Genetically Homologous and Genetically Heterologous P. Vivax Infections","description":"Two drops of peripheral blood were collected onto pre-printed filter paper for subsequent deoxyribonucleic acid (DNA) extraction and polymerase chain reaction (PCR) analysis of Plasmodium species on all participants at screening (Day 1; pre-dose) and; if necessary, at the time of the first recrudescence/relapse or re-infection. PCR of the P. vivax genes, was used to distinguish between genetically homologous and genetically heterologous infection. The number of participants with genetically homologous and genetically heterologous P. vivax infections has been summarized for each treatment group. Only those participants with an infection occuring on or after Study Day 33 were analyzed.","timeFrame":"Up to Day 180"},{"measure":"Number of Participants With Clinical Chemistry Laboratory Data Outside the Reference Range","description":"Plasma or serum samples were anlalyzed to evaluate clinical chemistry parameters such as alanine aminotransferase (ALT), alkaline phosphatase (ALP), aspartate aminotransferase (AST), bilirubin, creatine kinase, creatinine, glomerular filtration rate (GFR), indirect bilirubin and urea. The number of participants with clinical chemistry laboratory values outside the extended normal range (F3) has been presented. The upper and lower limits for F3 range were defined by multiplying the normal range limits by different factors. High and low indicated that the participants had values flagged as high and low respectively for the particular parameter any time on-treatment. Safety Population consisted of all randomized participants who received at least one dose of blinded study medication.","timeFrame":"Up to Day 120"},{"measure":"Number of Participants With Hematology Laboratory Data Outside the Reference Range","description":"Blood samples were collected for the evaluation of hematology parameters including eosinophils, leukocytes, lymphocytes, neutrophils, platelets, reticulocytes and methemoglobin. The number of participants with hematology laboratory data outside the extended normal range (F3) has been presented. The upper and lower limits for F3 range were defined by multiplying the normal range limits by different factors. High and low indicated that the participants had values flagged as high and low respectively for the particular parameter any time on-treatment. Participants having both High and Low values for Normal Ranges at any post-baseline visits for safety parameters were counted in both the High and Low categories.","timeFrame":"Up to Day 120"},{"measure":"Number of Participants With Abnormal Urinalysis Dipstick Results","description":"Mid-stream urine was collected and analyzed for bilirubin, glucose, ketones, leukocyte esterase (LE), nitrites, occult blood, proteins and urobilinogen by dipstick method. The number of participants with abnormal urinalysis results (Trace, +, ++, +++, ++++) has been presented. Only those participants with data available at the specified data points were analyzed.","timeFrame":"Up to Day 120"},{"measure":"Number of Participants With Treatment Emergent Adverse Events (TEAEs) and Serious TEAEs","description":"An adverse event (AE) is defined as any untoward medical occurrence in a participant under clinical investigation, temporally associated with the use of a medicinal product, whether or not considered related to the medicinal product. Serious adverse event (SAE) is defined as any untoward medical occurrence that, at any dose results in death, is life-threatening, requires hospitalization or prolongation of existing hospitalization, results in disability/incapacity, is a congenital anomaly/ birth defect, other situations such as important medical events and events of possible drug induced liver injury with hyperbilirubinemia. TEAEs are defined as AEs with an onset date and time on or after that of the start of first dose of study medication (including CQ). Number of participants with TEAEs and serious TEAEs have been presented.","timeFrame":"Up to Day 180"},{"measure":"Number of Participants With Electrocardiogram (ECG) Findings","description":"12 lead ECG was performed with the participant in a semi-supine position having rested in this position for at least 10 minutes. ECG assessments were performed in triplicate at screening followed by single ECGs 12 hours after the first dose of study medication and at Day 29. The number of participants with abnormal-clinically significant ECG findings have been presented. The 12 Hour Post Randomized Treatment (11.5-12.5 Hours) timepoint included all readings taken between 11.5 and 12.5 hours post randomized treatment. The 12 Hour Post Randomized Treatment (8-72 Hours) timepoint is a sensitivity analysis of the 12 Hour post randomized treatment timepoint, including all readings taken between 8 and 72 hours post randomized treatment. Only those participants with data available at the specified data points were analyzed (represented by n=X in category title).","timeFrame":"Up to Day 29"},{"measure":"Change From Baseline in Systolic Blood Pressure (SBP), Diastolic Blood Pressure (DBP) and Mean Arterial Pressure (MAP)","description":"Vital signs were measured twice a day on Days 1 through 3, at least 4 hours apart, and immediately prior to pharmacokinetic (PK) measurements. MAP was calculated as the sum of SBP and two times DBP divided by 3. The mean and standard deviation of SBP, DBP and MAP has been presented. The values presented does not include Day 3 assessments for participant number 570. Baseline value is defined as the latest pre-treatment assessment where treatment is their first dose of study medication (CQ/PQ/TQ/Placebo). Change from Baseline is the value at post dose minus Baseline value. Only those participants with data available at the specified data points were analyzed (represented by n=X in category title).","timeFrame":"Baseline and up to Day 180"},{"measure":"Change From Baseline in Pulse Rate","description":"Vital signs were measured twice a day on Days 1 through 3, at least 4 hours apart, and immediately prior to PK measurements. The mean and standard deviation of pulse rate has been presented. The values presented does not include Day 3 assessments for participant number 570. Baseline value is defined as the latest pre-treatment assessment where treatment is their first dose of study medication (CQ/PQ/TQ/Placebo). Change from Baseline is the value at post dose minus Baseline value. Only those participants with data available at the specified data points were analyzed (represented by n=X in category title).","timeFrame":"Baseline and up to Day 180"},{"measure":"Change From Baseline in Temperature","description":"Vital signs were performed twice a day on Days 1 through 3, at least 4 hours apart, and immediately prior to PK measurements. The mean and standard deviation of pulse rate has been presented. The values presented does not include Day 3 assessments for participant number 570. Baseline value is defined as the latest pre-treatment assessment where treatment is their first dose of study medication (CQ/PQ/TQ/Placebo). Change from Baseline is the value at post dose minus Baseline value. Only those participants with data available at the specified data points were analyzed (represented by n=X in category title).","timeFrame":"Baseline and up to Day 180"},{"measure":"Number of Participants With P. Falciparum","description":"Microscopic blood slides (two thick film and one thin film slide) were prepared and examined for asexual parasite count. The number of participants with positive P. falciparum asexual parasite count post Baseline has been summarized for each treatment arm.","timeFrame":"Up to Day 180"},{"measure":"Number of Participants With Keratopathy","description":"Ophthalmic assessments were carried out at pre-qualified sites prior to randomization and at Days 29 and 90 and at withdrawal follow-up visit. Assessments were carried out at Day 180 (and up to resolution) if the Day 90 assessments showed abnormalities. The last assessment performed on the day of randomization or earlier was considered Baseline. The number of participants displaying keratopathy in each eye has been summarized for each visit. The number of participants with new keratopathy at any time post Baseline is also reported. Ophthalmic Safety Population comprised of all participants in the Safety Population who have results from any eye assessments. Only those participants with data available at the specified data points were analyzed (represented by n=X in category title).","timeFrame":"Up to Day 180"},{"measure":"Number of Participants With Change in Best Corrected Visual Acuity Test Scores","description":"Ophthalmic assessments were carried out at pre-qualified sites prior to randomization and at Days 29 and 90 and at withdrawal. Assessments were carried out at Day 180 if the Day 90 assessments showed abnormalities. The last assessment performed on the day of randomization or earlier was considered Baseline. Change from Baseline is the value at post dose visit minus the Baseline value. Best corrected visual acuity was assessed individually for each eye. Scores were recorded as a ratio. The values were used to derive a logMAR score for statistical analysis where logMAR=-1x log10 (ratio score). The number of participants with change in Best Corrected Visual Acuity Test Scores from Baseline has been presented where possible change is defined as a change from Baseline \>=0.12 to \<0.3 and definite change is defined as a change from Baseline \>=0.3 logMAR score. Only those participants with data available at the specified data points were analyzed (represented by n=X in category title).","timeFrame":"Baseline and up to Day 180"},{"measure":"Number of Participants With Retinal Changes From Baseline","description":"Ophthalmic assessments were carried out at pre-qualified sites prior to randomization and at Days 29 and 90 and at withdrawal follow-up. Assessments were carried out at Day 180 (and up to resolution) if the Day 90 assessments showed abnormalities. The last assessment performed on the day of randomization or earlier was considered Baseline. Change from Baseline was calculated as the value at post dose visit minus the Baseline value. The number of participants with definite retinal change and questionable (ques) retinal change from Baseline has been presented. The number of participants with maximum change post-Baseline (definite when absent or questionable at Baseline) has been presented for either eye. Only those participants with data available at the specified data points were analyzed (represented by n=X in category title).","timeFrame":"Baseline and up to Day 180"},{"measure":"Change From Baseline in Percent Methemoglobin","description":"Methemoglbin is an oxidized and inactive form of hemoglobin. Methemoglobin assessment was made with the aid of a non-invasive signal extraction pulse CO-Oximeter handheld machine. The change from Baseline in percent methemoglobin by treatment, time and sex has been summarized. The latest pre-treatment assessment where treatment is their first dose of study medication (CQ/PQ/TQ/Placebo) was considered as Baseline value. Change from Baseline is the value at post dose visit minus the Baseline value. Only those participants with data available at the specified data points were analyzed (represented by n=X in category title).","timeFrame":"Baseline and up to Day 120"},{"measure":"Cost Associated With Relapse Episode of P Vivax Malaria","description":"Health outcomes were evaluated based on the total costs spent on treatment, transport, medication and tests. The cost was summarized according to the place at which the participant went to for care (drug shop, trial clinic, other clinic, hospital emergency center, other). The costs associated with a relapse episode of P. vivax malaria has been presented. Participants may be represented in more than one category, so the total number of participants may be less than the number quoted. Only those participants with data available at the specified data points were analyzed (represented by n=X in category title).","timeFrame":"Up to Day 180"},{"measure":"Cost Associated With a Hemolysis Event","description":"Health outcomes were evaluated based on cost incurred due to clinically relevant hemolysis. The total cost was evaluated based on the amount spent on treatment, transport, medication and test. The costs associated with hemolysis event has been presented. The aim of this outcome measure was to determine the cost to a participant due to an event of hemolysis, regardless of treatment received in the study. It was not expected there would be major cost differences with hemoglobin decrease between the treatment arms. This was pre-specified in the statistical analysis plan.","timeFrame":"Up to Day 180"},{"measure":"Cost Incurred With Purchase of Medications Associated With Relapse Episode of P. Vivax Malaria","description":"Health outcomes were evaluated based on the cost of medications purchased. The total medication cost for paracetamol associated with relapse episode of P vivax malaria has been presented. Medications recorded as "Other" and medications without costs are excluded from the analysis. Only those participants with data available at the specified data points were analyzed (represented by n=X in category title).","timeFrame":"Up to Day 180"},{"measure":"Cost Incurred With Purchase of Medications Associated With Hemolysis Event","description":"Health outcomes were evaluated based on the cost of medications purchased. The total medication cost associated with hemolysis event has been presented. Medications recorded as "Other" and medications without costs are excluded from the analysis. The aim of this outcome measure was to determine the cost to a participant due to an event of hemolysis, regardless of treatment received in the study. It was not expected there would be major cost differences with hemoglobin decrease between the treatment arms. This was pre-specified in the statistical analysis plan.","timeFrame":"Up to Day 180"},{"measure":"Number of Participants or Care Givers Who Had Taken Time Off From Normal Occupation Due to Relapse Episode of Malaria","description":"Health outcomes were evaluated based on total time lost by participants or care givers due to an episode of malaria. The number of participants or care givers who had taken off from their normal occupation due to relapse episode of P vivax malaria has been presented by country. Participants may be represented in more than one category, so the total number of participants may be less than the number quoted. Only those participants with data available at the specified data points were analyzed (represented by n=X in category title).","timeFrame":"Up to Day 180"},{"measure":"Number of Participants or Care Givers Who Had Taken Time Off From Normal Occupation Due to a Hemolysis Event","description":"Health outcomes were evaluated based on total time lost by participants or care givers due to a hemolysis event. The number of participants or care givers who took days off from work due to a hemolysis event has been presented based on the normal occupation. The aim of this outcome measure was to determine the time taken off by participants due to an event of hemolysis, regardless of treatment received in the study. It was not expected there would be major differences in time taken off by participants with hemoglobin decrease between the treatment arms. This was pre-specified in the statistical analysis plan.","timeFrame":"Up to Day 180"},{"measure":"Number of Participants With Action Taken to Treat Relapse Episode of P. Vivax Malaria","description":"Health outcomes were evaluated based on the actions taken by the participants to treat relapse episode of P vivax malaria. The number of participants with the type of action taken to treat relapse episode of P vivax malaria has been presented by country. Participants may be represented in more than one category, so the total number of participants may be less than the number quoted. Only those participants with data available at the specified data points were analyzed (represented by n=X in category title).","timeFrame":"Up to Day 180"},{"measure":"Number of Participants With Action Taken to Treat a Hemolysis Event","description":"Health outcomes were evaluated based on the actions taken by the participants to treat hemolysis events. The number of participants in Brazil who attended the trial clinic to treat a hemolysis event has been presented. The aim of this outcome measure was to determine the action taken by a participant due to an event of hemolysis, regardless of treatment received in the study. It was not expected there would be major differences in action taken by the participants with hemoglobin decrease between the treatment arms. This was pre-specified in the statistical analysis plan.","timeFrame":"Up to Day 180"},{"measure":"Oral Clearance (CL/F) of TQ","description":"Apparent population oral clearance of TQ","timeFrame":"Day 2, Day 3, Day 8, Day 15, Day 29, Day 60 and Day 180"},{"measure":"Volume of Distribution (Vc/F) of TQ","description":"Apparent population central volume of distribution of TQ","timeFrame":"Day 2, Day 3, Day 8, Day 15, Day 29, Day 60 and Day 180"}]},"eligibilityModule":{"eligibilityCriteria":"Inclusion Criteria:

* A female is eligible to enter and participate in the study if she is non-pregnant, nonlactating and if she is of: a. Non-childbearing potential defined as: post-menopausal (12 months of spontaneous amenorrhea or \<6 months of spontaneous amenorrhea with serum follicle-stimulating hormone \>40 milli-International units per milliliter \[mIU/mL\]), or pre-menopausal and has had a hysterectomy or a bilateral oophorectomy (removal of the ovaries) or a bilateral tubal ligation, negative pregnancy test or, b. Child-bearing potential, has a negative pregnancy test at screening, and agrees to comply with one of the following during the treatment stage of the study and for a period of 90 days after stopping study medication: Use of oral contraceptive, either combined or progestogen alone used in conjunction with double barrier method as defined below. Use of an intrauterine device with a documented failure rate of \<1% per year; Use of depo provera injection; Double barrier method consisting of spermicide with either condom or diaphragm; Male partner who is sterile prior to the female subject's entry into the study and is the sole sexual partner for that female. Complete abstinence from intercourse for 2 weeks prior to administration of study medication, throughout the study and for a period of 90 days after stopping study medication.
* The subject has a glucose 6-phosphate dehydrogenase (G6PD) value (measured by a quantitative spectrophotometric phenotype assay) as follows: Female subjects must have an enzyme level \>= 40 percent of the site median value for G6PD normal males. Male subjects must have an enzyme level \>= 70 percent of the site median value for G6PD normal males.
* The subject has a screening hemoglobin (Hb) value as follows: Any subject with a G6PD value \>=70 percent of the site median value must have a screening Hb value \>=7 g/dL; Female subjects with a G6PD value is \>=40 - \<70 percent of the site median value must have a screening Hb value \>=8 g/dL.
* The subject has a QT duration corrected for heart rate by Fridericia's Formula (QTcF) \<450 milisecond (msec). Reading based on an average of triplicate Electrocardiograms (ECGs) obtained over a brief recording period by machine or manual over-read.
* The subject has a positive malarial smear for P. vivax .
* The subject has a parasite density of \>100 and \<100,000 per microliter (μL).
* Male or female subject aged 16 years or older (18 years or older in Ethiopia) at the time of signing the informed consent.
* The subject agrees to G6PD genotyping.
* The subject is willing and able to comply with the study protocol.
* The subject or parent/legal guardian, as applicable, has given written informed, dated consent; and the subject has given written assent, if applicable, to participate in the study.

Exclusion Criteria:

* The subject has a mixed malaria infection (identified by a malarial smear or rapid diagnostic test).
* The subject has severe P. vivax malaria as defined by World Health Organization (WHO) criteria.
* The subject has a history of allergy to chloroquine, mefloquine, tafenoquine, primaquine, or to any other 4- or 8-aminoquinoline.
* The subject has a liver alanine aminotransferase (ALT) \>2 x upper limit of normal (ULN).
* The subject has severe vomiting (no food or inability to take food during the previous 8 hours).
* The subject has a clinically significant concurrent illness (e.g., pneumonia, septicemia), pre-existing condition (e.g., renal disease, malignancy), condition that may affect absorption of study medication (e.g., vomiting, severe diarrhea), or clinical signs and symptoms of severe cardiovascular disease (e.g., uncontrolled congestive heart failure, severe coronary artery disease).
* The subject has a history of porphyria, psoriasis, or epilepsy.
* The subject has a history of significant ocular disease (e.g. surgery to the globe, glaucoma, diabetic retinopathy) or has evidence of corneal or retinal abnormalities identified in the clinical screening ophthalmologic examination.
* The subject has taken anti-malarials (e.g., artemisinin-based combination therapies, mefloquine, primaquine, or any other 4- or 8-aminoquinoline) within 30 days prior to study entry.
* The subject has taken or will likely require during the study the use of medications from the following classes: Histamine-2 blockers and antacids; Drugs with hemolytic potential; Drugs known to prolong the QTcF interval; The biguanides phenformin and buformin (but excluding metformin); Drugs that are substrates of the renal transporters OCT2, MATE1 AND MATE-2K and have a narrow therapeutic index (for example, the anti-arrhythmic agents dofetilide, procainamide and pilsicainide)
* The subject has received treatment with any investigational drug within 30 days of study entry, or within 5 half-lives, whichever is longer.
* The subject has a recent history of illicit drug abuse or heavy alcohol intake, such that full participation in the study could be compromised.","healthyVolunteers":false,"sex":"ALL","minimumAge":"16 Years","stdAges":["CHILD","ADULT","OLDER_ADULT"]},"contactsLocationsModule":{"overallOfficials":[{"name":"GSK Clinical Trials","affiliation":"GlaxoSmithKline","role":"STUDY_DIRECTOR"}],"locations":[{"facility":"GSK Investigational Site","city":"Manaus","state":"Amazonas","zip":"69040-000","country":"Brazil","geoPoint":{"lat":-3.10194,"lon":-60.025}},{"facility":"GSK Investigational Site","city":"Cali","country":"Colombia","geoPoint":{"lat":3.43054,"lon":-76.5199}},{"facility":"GSK Investigational Site","city":"Montería","country":"Colombia","geoPoint":{"lat":8.75081,"lon":-75.87823}},{"facility":"GSK Investigational Site","city":"Gonder","country":"Ethiopia","geoPoint":{"lat":12.6,"lon":37.46667}},{"facility":"GSK Investigational Site","city":"Jimma","country":"Ethiopia","geoPoint":{"lat":7.67344,"lon":36.83441}},{"facility":"GSK Investigational Site","city":"Iquitos","state":"Loreto","zip":"Iqui 01","country":"Peru","geoPoint":{"lat":-3.74814,"lon":-73.2529}},{"facility":"GSK Investigational Site","city":"Bangkok","zip":"10400","country":"Thailand","geoPoint":{"lat":13.75398,"lon":100.50144}},{"facility":"GSK Investigational Site","city":"Mae Sot","zip":"63110","country":"Thailand","geoPoint":{"lat":16.71667,"lon":98.56667}},{"facility":"GSK Investigational Site","city":"Tak","zip":"63170","country":"Thailand","geoPoint":{"lat":16.86968,"lon":99.12898}},{"facility":"GSK Investigational Site","city":"Ho Chi Minh City","country":"Vietnam","geoPoint":{"lat":10.82302,"lon":106.62965}}]},"referencesModule":{"references":[{"pmid":"30650326","type":"DERIVED","citation":"Llanos-Cuentas A, Lacerda MVG, Hien TT, Velez ID, Namaik-Larp C, Chu CS, Villegas MF, Val F, Monteiro WM, Brito MAM, Costa MRF, Chuquiyauri R, Casapia M, Nguyen CH, Aruachan S, Papwijitsil R, Nosten FH, Bancone G, Angus B, Duparc S, Craig G, Rousell VM, Jones SW, Hardaker E, Clover DD, Kendall L, Mohamed K, Koh GCKW, Wilches VM, Breton JJ, Green JA. Tafenoquine versus Primaquine to Prevent Relapse of Plasmodium vivax Malaria. N Engl J Med. 2019 Jan 17;380(3):229-241. doi: 10.1056/NEJMoa1802537."}]}},"resultsSection":{"participantFlowModule":{"preAssignmentDetails":"A total of 369 participants were screened of which 118 failed screening and 251 participants were randomized to receive either TQ+chloroquine (CQ) or PQ+CQ in a ratio of 2:1.","recruitmentDetails":"This is a randomized, double-blind, double-dummy, comparative, multicenter study to assess the incidence of hemolysis, safety and efficacy of Tafenoquine (TQ) versus Primaquine (PQ) in treatment of participants with Plasmodium vivax (P. vivax) malaria.","groups":[{"id":"FG000","title":"TQ+CQ","description":"Participants were administered CQ 600 milligram (mg) once daily on Days 1 and 2 and CQ 300 mg on Day 3. A single dose of TQ 300 mg was administered orally on Day 1 or Day 2. PQ placebo capsules were administered orally once daily for 14 days starting on the same day as TQ administration."},{"id":"FG001","title":"PQ+CQ","description":"Participants were administered CQ 600 mg tablet once daily on Days 1 and 2 and CQ 300 mg on Day 3. Participants received a single TQ placebo tablet orally on Day 1 or Day 2. PQ 15 mg was administered orally once daily for 14 days starting on the same day as TQ placebo administration."}],"periods":[{"title":"Overall Study","milestones":[{"type":"STARTED","achievements":[{"groupId":"FG000","numSubjects":"166"},{"groupId":"FG001","numSubjects":"85"}]},{"type":"COMPLETED","achievements":[{"groupId":"FG000","numSubjects":"160"},{"groupId":"FG001","numSubjects":"83"}]},{"type":"NOT COMPLETED","achievements":[{"groupId":"FG000","numSubjects":"6"},{"groupId":"FG001","numSubjects":"2"}]}],"dropWithdraws":[{"type":"Lost to Follow-up","reasons":[{"groupId":"FG000","numSubjects":"4"},{"groupId":"FG001","numSubjects":"2"}]},{"type":"Withdrawal by Subject","reasons":[{"groupId":"FG000","numSubjects":"2"},{"groupId":"FG001","numSubjects":"0"}]}]}]},"baselineCharacteristicsModule":{"groups":[{"id":"BG000","title":"TQ+CQ","description":"Participants were administered CQ 600 milligram (mg) once daily on Days 1 and 2 and CQ 300 mg on Day 3. A single dose of TQ 300 mg was administered orally on Day 1 or Day 2. PQ placebo capsules were administered orally once daily for 14 days starting on the same day as TQ administration."},{"id":"BG001","title":"PQ+CQ","description":"Participants were administered CQ 600 mg tablet once daily on Days 1 and 2 and CQ 300 mg on Day 3. Participants received a single TQ placebo tablet orally on Day 1 or Day 2. PQ 15 mg was administered orally once daily for 14 days starting on the same day as TQ placebo administration."},{"id":"BG002","title":"Total","description":"Total of all reporting groups"}],"denoms":[{"units":"Participants","counts":[{"groupId":"BG000","value":"166"},{"groupId":"BG001","value":"85"},{"groupId":"BG002","value":"251"}]}],"measures":[{"title":"Age, Continuous","paramType":"MEAN","dispersionType":"STANDARD_DEVIATION","unitOfMeasure":"Years","classes":[{"categories":[{"measurements":[{"groupId":"BG000","value":"37.5","spread":"14.28"},{"groupId":"BG001","value":"37.7","spread":"14.69"},{"groupId":"BG002","value":"37.6","spread":"14.39"}]}]}]},{"title":"Sex: Female, Male","paramType":"COUNT_OF_PARTICIPANTS","unitOfMeasure":"Participants","classes":[{"categories":[{"title":"Female","measurements":[{"groupId":"BG000","value":"52"},{"groupId":"BG001","value":"32"},{"groupId":"BG002","value":"84"}]},{"title":"Male","measurements":[{"groupId":"BG000","value":"114"},{"groupId":"BG001","value":"53"},{"groupId":"BG002","value":"167"}]}]}]},{"title":"Race/Ethnicity, Customized","paramType":"NUMBER","unitOfMeasure":"Count of Participants","classes":[{"title":"American (Amer) Indian (Ind) or Alaska Native (N)","categories":[{"measurements":[{"groupId":"BG000","value":"87"},{"groupId":"BG001","value":"43"},{"groupId":"BG002","value":"130"}]}]},{"title":"Asian-East Asian Heritage","categories":[{"measurements":[{"groupId":"BG000","value":"6"},{"groupId":"BG001","value":"3"},{"groupId":"BG002","value":"9"}]}]},{"title":"Asian-South East Asian Heritage","categories":[{"measurements":[{"groupId":"BG000","value":"35"},{"groupId":"BG001","value":"20"},{"groupId":"BG002","value":"55"}]}]},{"title":"Black or African Amer","categories":[{"measurements":[{"groupId":"BG000","value":"2"},{"groupId":"BG001","value":"0"},{"groupId":"BG002","value":"2"}]}]},{"title":"African Amer/African Heritage/Amer Ind or Alaska N","categories":[{"measurements":[{"groupId":"BG000","value":"36"},{"groupId":"BG001","value":"19"},{"groupId":"BG002","value":"55"}]}]}]}]},"outcomeMeasuresModule":{"outcomeMeasures":[{"type":"PRIMARY","title":"Percentage of Participants With Clinically Relevant Hemolysis.","description":"Clinically relevant hemolysis is defined as a decrease in hemoglobin of \>=30% or \>3 grams per deciliter (g/dL) from Baseline; or, an overall drop in hemoglobin below 6.0 g/dL at any visit after the first dose of study medication. The percentage of participants with clinically relevant hemolysis has been summarized. Safety Population comprised of all randomized participants who received at least one dose of blinded study medication.","populationDescription":"Safety Population","reportingStatus":"POSTED","paramType":"NUMBER","dispersionType":"95% Confidence Interval","unitOfMeasure":"Percentage of participants","timeFrame":"Up to Day 180","groups":[{"id":"OG000","title":"TQ+CQ","description":"Participants were administered CQ 600 milligram (mg) once daily on Days 1 and 2 and CQ 300 mg on Day 3. A single dose of TQ 300 mg was administered orally on Day 1 or Day 2. PQ placebo capsules were administered orally once daily for 14 days starting on the same day as TQ administration."},{"id":"OG001","title":"PQ+CQ","description":"Participants were administered CQ 600 mg tablet once daily on Days 1 and 2 and CQ 300 mg on Day 3. Participants received a single TQ placebo tablet orally on Day 1 or Day 2. PQ 15 mg was administered orally once daily for 14 days starting on the same day as TQ placebo administration."}],"denoms":[{"units":"Participants","counts":[{"groupId":"OG000","value":"166"},{"groupId":"OG001","value":"85"}]}],"classes":[{"categories":[{"measurements":[{"groupId":"OG000","value":"2.41","lowerLimit":"0.941","upperLimit":"6.031"},{"groupId":"OG001","value":"1.18","lowerLimit":"0.208","upperLimit":"6.367"}]}]}],"analyses":[{"groupIds":["OG000","OG001"],"nonInferiorityType":"OTHER","paramType":"Mean Difference (Final Values)","paramValue":"1.23","ciPctValue":"95","ciNumSides":"TWO_SIDED","ciLowerLimit":"-4.161","ciUpperLimit":"4.982","estimateComment":"Confidence interval for the treatment difference was based on the Newcombe method. Percent treatment difference (TQ+CQ-PQ+CQ) has been presented."}]},{"type":"PRIMARY","title":"Percentage of Female Participants With Moderate Glucose-6 Phosphate Dehydrogenase (G6PD) Deficiency Experiencing Clinically Relevant Hemolysis.","description":"Clinically relevant hemolysis is defined as a decrease in hemoglobin of \>=30% or \>3 g/dL from Baseline; or, an overall drop in hemoglobin below 6.0 g/dL at any visit after the first dose of study medication. Despite additional efforts, no females with moderate G6PD-deficiency were enrolled that experienced clinically-significant hemolysis during the study; hence, the end point could not be estimated.","populationDescription":"Safety Population","reportingStatus":"POSTED","timeFrame":"Up to Day 180","groups":[{"id":"OG000","title":"TQ+CQ","description":"Participants were administered CQ 600 milligram (mg) once daily on Days 1 and 2 and CQ 300 mg on Day 3. A single dose of TQ 300 mg was administered orally on Day 1 or Day 2. PQ placebo capsules were administered orally once daily for 14 days starting on the same day as TQ administration."},{"id":"OG001","title":"PQ+CQ","description":"Participants were administered CQ 600 mg tablet once daily on Days 1 and 2 and CQ 300 mg on Day 3. Participants received a single TQ placebo tablet orally on Day 1 or Day 2. PQ 15 mg was administered orally once daily for 14 days starting on the same day as TQ placebo administration."}],"denoms":[{"units":"Participants","counts":[{"groupId":"OG000","value":"0"},{"groupId":"OG001","value":"0"}]}]},{"type":"SECONDARY","title":"Rate of Relapse-free Efficacy at Six Months Post Dose","description":"A participant was considered to have demonstrated relapse-free efficacy at 6 months if: a) Participant had non-zero P. vivax asexual parasite count at Baseline. b) Participant showed initial clearance of P. vivax parasitemia defined as two negative asexual P. vivax parasite counts, with at least 6 hours between the counts, and no positive counts in the interval. c) Participant had no positive asexual P. vivax parasite count at any assessment prior to or on Study Day 201 following initial parasite clearance. d) Participant did not take a concomitant medication with anti-malarial activity at any point between Study Day 1 and their last parasite assessment. e) Participant is parasite-free at 6 months. The rate of relapse-free efficacy was estimated by Kaplan-Meier methodology. The percentage of participants who were relapse-free at 6 months post dose has been presented along with 95% confidence interval.","populationDescription":"Microbiologic-Intent-To-Treat (mITT) Population comprised of all randomized participants who received at least one dose of blinded study medication and had microscopically-confimed P. vivax parasitemia at Baseline.","reportingStatus":"POSTED","paramType":"NUMBER","dispersionType":"95% Confidence Interval","unitOfMeasure":"Percentage of participants","timeFrame":"6 months post dose","groups":[{"id":"OG000","title":"TQ+CQ","description":"Participants were administered CQ 600 milligram (mg) once daily on Days 1 and 2 and CQ 300 mg on Day 3. A single dose of TQ 300 mg was administered orally on Day 1 or Day 2. PQ placebo capsules were administered orally once daily for 14 days starting on the same day as TQ administration."},{"id":"OG001","title":"PQ+CQ","description":"Participants were administered CQ 600 mg tablet once daily on Days 1 and 2 and CQ 300 mg on Day 3. Participants received a single TQ placebo tablet orally on Day 1 or Day 2. PQ 15 mg was administered orally once daily for 14 days starting on the same day as TQ placebo administration."}],"denoms":[{"units":"Participants","counts":[{"groupId":"OG000","value":"166"},{"groupId":"OG001","value":"85"}]}],"classes":[{"categories":[{"measurements":[{"groupId":"OG000","value":"72.7","lowerLimit":"64.8","upperLimit":"79.2"},{"groupId":"OG001","value":"75.1","lowerLimit":"64.2","upperLimit":"83.2"}]}]}],"analyses":[{"groupIds":["OG000","OG001"],"nonInferiorityType":"OTHER","paramType":"Hazard Ratio (HR)","paramValue":"0.984","ciPctValue":"95","ciLowerLimit":"0.577","ciUpperLimit":"1.678","estimateComment":"Hazards ratio was estimated from Cox Proportional Hazards Model with treatment and region as covariates. A hazard ratio \<1 indicates a lower chance of relapse with TQ+CQ compared to PQ+CQ."}]},{"type":"SECONDARY","title":"Rate of Relapse-free Efficacy at Four Months Post Dose","description":"A participant was considered to have demonstrated recurrence-free efficacy at 4 months if: a) Participant had non-zero P. vivax asexual parasite count at Baseline. b) Participant showed initial clearance of P. vivax parasitemia. c) Participant had no positive asexual P. vivax parasite count at any assessment prior to or on Study Day 130 following initial parasite clearance. d) Participant did not take a concomitant medication with anti-malarial activity at any point between Study Day 1 and their last parasite assessment after Study Day 109 (up to and including Study Day 130). e) Participant is parasite-free at 4 months. The rate of relapse-free efficacy was estimated by Kaplan-Meier methodology. The percentage of participants who were relapse-free at 4 months post dose has been presented along with 95% confidence interval.","populationDescription":"mITT Population","reportingStatus":"POSTED","paramType":"NUMBER","dispersionType":"95% Confidence Interval","unitOfMeasure":"Percentage of participants","timeFrame":"4 months post dose","groups":[{"id":"OG000","title":"TQ+CQ","description":"Participants were administered CQ 600 milligram (mg) once daily on Days 1 and 2 and CQ 300 mg on Day 3. A single dose of TQ 300 mg was administered orally on Day 1 or Day 2. PQ placebo capsules were administered orally once daily for 14 days starting on the same day as TQ administration."},{"id":"OG001","title":"PQ+CQ","description":"Participants were administered CQ 600 mg tablet once daily on Days 1 and 2 and CQ 300 mg on Day 3. Participants received a single TQ placebo tablet orally on Day 1 or Day 2. PQ 15 mg was administered orally once daily for 14 days starting on the same day as TQ placebo administration."}],"denoms":[{"units":"Participants","counts":[{"groupId":"OG000","value":"166"},{"groupId":"OG001","value":"85"}]}],"classes":[{"categories":[{"measurements":[{"groupId":"OG000","value":"82.3","lowerLimit":"74.9","upperLimit":"87.7"},{"groupId":"OG001","value":"79.7","lowerLimit":"68.9","upperLimit":"87.1"}]}]}],"analyses":[{"groupIds":["OG000","OG001"],"nonInferiorityType":"OTHER","paramType":"Hazard Ratio (HR)","paramValue":"0.815","ciPctValue":"95","ciNumSides":"TWO_SIDED","ciLowerLimit":"0.442","ciUpperLimit":"1.503","estimateComment":"Hazard ratio was estimated from Cox Proportional Hazards Model with treatment and region as covariates. A hazard ratio\<1 indicates a lower chance of relapse with TQ+CQ compared to PQ+CQ."}]},{"type":"SECONDARY","title":"Time to Relapse of P. Vivax Malaria","description":"Relapse is defined by a positive blood smear with or without vivax symptoms. Relapse is described as any recurrence of malaria that occurred after Day 32 of the study. The time to relapse was analyzed by the Kaplan-Meier method. The median number of days to relapse along with 95% confidence interval has been presented for each treatment group.","populationDescription":"mITT Population","reportingStatus":"POSTED","paramType":"MEDIAN","dispersionType":"95% Confidence Interval","unitOfMeasure":"Days","timeFrame":"Up to Day 180","groups":[{"id":"OG000","title":"TQ+CQ","description":"Participants were administered CQ 600 milligram (mg) once daily on Days 1 and 2 and CQ 300 mg on Day 3. A single dose of TQ 300 mg was administered orally on Day 1 or Day 2. PQ placebo capsules were administered orally once daily for 14 days starting on the same day as TQ administration."},{"id":"OG001","title":"PQ+CQ","description":"Participants were administered CQ 600 mg tablet once daily on Days 1 and 2 and CQ 300 mg on Day 3. Participants received a single TQ placebo tablet orally on Day 1 or Day 2. PQ 15 mg was administered orally once daily for 14 days starting on the same day as TQ placebo administration."}],"denoms":[{"units":"Participants","counts":[{"groupId":"OG000","value":"166"},{"groupId":"OG001","value":"85"}]}],"classes":[{"categories":[{"measurements":[{"groupId":"OG000","value":"NA","lowerLimit":"NA","upperLimit":"NA","comment":"The median estimate for the time to relapse is the time taken (in days) for 50% of participants to relapse. As less than 50% of participants in both treatment arms relapsed during the study, the median times to relapse could not be calculated."},{"groupId":"OG001","value":"NA","lowerLimit":"NA","upperLimit":"NA","comment":"The median estimate for the time to relapse is the time taken (in days) for 50% of participants to relapse. As less than 50% of participants in both treatment arms relapsed during the study, the median times to relapse could not be calculated."}]}]}]},{"type":"SECONDARY","title":"Time to Parasite Clearance","description":"Parasite clearance time is defined as time needed to clear asexual parasite from the blood that is, parasite numbers falling below the limit of detection in the thick blood smear and remaining undetectable after 6 to 12 hours later. The time to achieve parasite clearance was analyzed by Kaplan-Meier methodology. The median parasite clearance time along with 95% confidence interval has been presented for each treatment group.","populationDescription":"mITT Population","reportingStatus":"POSTED","paramType":"MEDIAN","dispersionType":"95% Confidence Interval","unitOfMeasure":"Hours","timeFrame":"Up to Day 180","groups":[{"id":"OG000","title":"TQ+CQ","description":"Participants were administered CQ 600 milligram (mg) once daily on Days 1 and 2 and CQ 300 mg on Day 3. A single dose of TQ 300 mg was administered orally on Day 1 or Day 2. PQ placebo capsules were administered orally once daily for 14 days starting on the same day as TQ administration."},{"id":"OG001","title":"PQ+CQ","description":"Participants were administered CQ 600 mg tablet once daily on Days 1 and 2 and CQ 300 mg on Day 3. Participants received a single TQ placebo tablet orally on Day 1 or Day 2. PQ 15 mg was administered orally once daily for 14 days starting on the same day as TQ placebo administration."}],"denoms":[{"units":"Participants","counts":[{"groupId":"OG000","value":"166"},{"groupId":"OG001","value":"85"}]}],"classes":[{"categories":[{"measurements":[{"groupId":"OG000","value":"41","lowerLimit":"38","upperLimit":"45"},{"groupId":"OG001","value":"44","lowerLimit":"41","upperLimit":"49"}]}]}]},{"type":"SECONDARY","title":"Time to Fever Clearance","description":"Fever clearance time is defined as the time from first dose of treatment to the time when body temperature falls to normal within Study Days 1-4 and remains normal for at least 48 hours up to the Day 8 visit. Fever clearance was considered to have been achieved once an initial temperature of more than 37.4 degree Celsius is reduced to a value less than or equal to 37.4 degree Celsius, in the absence of value more than 37.4 degree Celsius in the following 48 hours up to the Day 8 visit. The time taken to achieve fever clearance was analyzed by Kaplan-Meier method.","populationDescription":"mITT Population","reportingStatus":"POSTED","paramType":"MEDIAN","dispersionType":"95% Confidence Interval","unitOfMeasure":"Hours","timeFrame":"Up to Day 9","groups":[{"id":"OG000","title":"TQ+CQ","description":"Participants were administered CQ 600 milligram (mg) once daily on Days 1 and 2 and CQ 300 mg on Day 3. A single dose of TQ 300 mg was administered orally on Day 1 or Day 2. PQ placebo capsules were administered orally once daily for 14 days starting on the same day as TQ administration."},{"id":"OG001","title":"PQ+CQ","description":"Participants were administered CQ 600 mg tablet once daily on Days 1 and 2 and CQ 300 mg on Day 3. Participants received a single TQ placebo tablet orally on Day 1 or Day 2. PQ 15 mg was administered orally once daily for 14 days starting on the same day as TQ placebo administration."}],"denoms":[{"units":"Participants","counts":[{"groupId":"OG000","value":"166"},{"groupId":"OG001","value":"85"}]}],"classes":[{"categories":[{"measurements":[{"groupId":"OG000","value":"10","lowerLimit":"7","upperLimit":"19"},{"groupId":"OG001","value":"13","lowerLimit":"8","upperLimit":"22"}]}]}]},{"type":"SECONDARY","title":"Time to Gametocyte Clearance","description":"Gametocyte clearance time is defined as time from first dose until the first slide that was gametocyte negative and remained so at the next slide reading. The time taken to achieve gametocyte clearance was analyzed by Kaplan-Meier method.","populationDescription":"mITT Population","reportingStatus":"POSTED","paramType":"MEDIAN","dispersionType":"95% Confidence Interval","unitOfMeasure":"Hours","timeFrame":"Up to Day 180","groups":[{"id":"OG000","title":"TQ+CQ","description":"Participants were administered CQ 600 milligram (mg) once daily on Days 1 and 2 and CQ 300 mg on Day 3. A single dose of TQ 300 mg was administered orally on Day 1 or Day 2. PQ placebo capsules were administered orally once daily for 14 days starting on the same day as TQ administration."},{"id":"OG001","title":"PQ+CQ","description":"Participants were administered CQ 600 mg tablet once daily on Days 1 and 2 and CQ 300 mg on Day 3. Participants received a single TQ placebo tablet orally on Day 1 or Day 2. PQ 15 mg was administered orally once daily for 14 days starting on the same day as TQ placebo administration."}],"denoms":[{"units":"Participants","counts":[{"groupId":"OG000","value":"166"},{"groupId":"OG001","value":"85"}]}],"classes":[{"categories":[{"measurements":[{"groupId":"OG000","value":"38","lowerLimit":"37","upperLimit":"43"},{"groupId":"OG001","value":"41","lowerLimit":"37","upperLimit":"48"}]}]}]},{"type":"SECONDARY","title":"Number of Participants With Recrudescence","description":"Recrudescence is defined as any P. vivax parasitemia occurring on or before Day 32 (that is, blood stage treatment failure). A participant was considered to have had a recrudescence if both of the following were true: a) Participant had a positive P. vivax asexual parasite count at Baseline and demonstrated clearance (that is, did not have two negative asexual P. vivax parasite counts, with at least 6 hours between the counts, and no positive counts in the interval). b) Participant had a positive genetically homologous asexual P. vivax parasite count, after their zero count in Days 1 to 5, but on or before Study Day 32. The number of participants with recrudescence before Study Day 33 has been presented.","populationDescription":"mITT Population","reportingStatus":"POSTED","paramType":"NUMBER","unitOfMeasure":"Participants","timeFrame":"Up to Day 32","groups":[{"id":"OG000","title":"TQ+CQ","description":"Participants were administered CQ 600 milligram (mg) once daily on Days 1 and 2 and CQ 300 mg on Day 3. A single dose of TQ 300 mg was administered orally on Day 1 or Day 2. PQ placebo capsules were administered orally once daily for 14 days starting on the same day as TQ administration."},{"id":"OG001","title":"PQ+CQ","description":"Participants were administered CQ 600 mg tablet once daily on Days 1 and 2 and CQ 300 mg on Day 3. Participants received a single TQ placebo tablet orally on Day 1 or Day 2. PQ 15 mg was administered orally once daily for 14 days starting on the same day as TQ placebo administration."}],"denoms":[{"units":"Participants","counts":[{"groupId":"OG000","value":"166"},{"groupId":"OG001","value":"85"}]}],"classes":[{"categories":[{"measurements":[{"groupId":"OG000","value":"0"},{"groupId":"OG001","value":"0"}]}]}]},{"type":"SECONDARY","title":"Number of Participants With Genetically Homologous and Genetically Heterologous P. Vivax Infections","description":"Two drops of peripheral blood were collected onto pre-printed filter paper for subsequent deoxyribonucleic acid (DNA) extraction and polymerase chain reaction (PCR) analysis of Plasmodium species on all participants at screening (Day 1; pre-dose) and; if necessary, at the time of the first recrudescence/relapse or re-infection. PCR of the P. vivax genes, was used to distinguish between genetically homologous and genetically heterologous infection. The number of participants with genetically homologous and genetically heterologous P. vivax infections has been summarized for each treatment group. Only those participants with an infection occuring on or after Study Day 33 were analyzed.","populationDescription":"mITT Population. Only those participants who had a recurrence of infection were included in the analysis.","reportingStatus":"POSTED","paramType":"NUMBER","unitOfMeasure":"Participants","timeFrame":"Up to Day 180","groups":[{"id":"OG000","title":"TQ+CQ","description":"Participants were administered CQ 600 milligram (mg) once daily on Days 1 and 2 a